import{_ as e,o as t,c as r,ae as s}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"Orchestraとは","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/what-is-orchestra.md","filePath":"ja/guide/what-is-orchestra.md"}'),l={name:"ja/guide/what-is-orchestra.md"};function o(i,a,n,c,d,h){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="orchestraとは" tabindex="-1">Orchestraとは <a class="header-anchor" href="#orchestraとは" aria-label="Permalink to &quot;Orchestraとは&quot;">​</a></h1><p>OrchestraはAIコーディングエージェント（<a href="https://claude.ai/code" target="_blank" rel="noreferrer">Claude Code</a>等）のセッション状態をリアルタイムで監視するmacOSデスクトップアプリです。Hooksを通じて全てのアクティブなセッションを統合ダッシュボードで管理できます。</p><h2 id="課題" tabindex="-1">課題 <a class="header-anchor" href="#課題" aria-label="Permalink to &quot;課題&quot;">​</a></h2><p>複数のClaude Codeセッションを異なるプロジェクトで同時に実行していると、以下のことが把握しにくくなります:</p><ul><li>どのセッションが入力待ちか</li><li>どのセッションが権限承認を必要としているか</li><li>どのセッションがタスクを完了したか</li><li>どのセッションがサブエージェントやチーム操作を実行中か</li></ul><p>ステータスを確認するために、常にターミナルウィンドウを切り替える必要があります。</p><h2 id="解決策" tabindex="-1">解決策 <a class="header-anchor" href="#解決策" aria-label="Permalink to &quot;解決策&quot;">​</a></h2><p>Orchestraはバックグラウンドで動作し、全てのClaude Codeセッションを単一のダッシュボードで監視します。セッションがあなたの注意を必要とした時、通知とワンクリックジャンプ機能で素早く対応できます。</p><h2 id="主要機能" tabindex="-1">主要機能 <a class="header-anchor" href="#主要機能" aria-label="Permalink to &quot;主要機能&quot;">​</a></h2><ul><li><strong>リアルタイム監視</strong> — ライブステータス更新で全セッションを一目で確認</li><li><strong>スマートキューシステム</strong> — 入力待ち・権限要求・エラー時に自動アラート</li><li><strong>ワンクリックジャンプ</strong> — tmux + iTerm2連携でセッション間を瞬時に移動</li><li><strong>チームモード</strong> — Claude Code Agent Teamsを自動検出し、虹色枠で視覚化</li><li><strong>サブエージェント追跡</strong> — セッションごとのアクティブサブエージェント数を追跡</li><li><strong>ネイティブmacOS</strong> — システム通知とサウンド対応の軽量Tauriアプリ</li></ul><h2 id="仕組み" tabindex="-1">仕組み <a class="header-anchor" href="#仕組み" aria-label="Permalink to &quot;仕組み&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude Code Hook → HTTP POST → Orchestra (port 3008) → デスクトップUI</span></span>
<span class="line"><span>                                                      → システム通知</span></span>
<span class="line"><span>                                                      → サウンドアラート</span></span></code></pre></div><ol><li>Claude Codeがhookイベント（PreToolUse, PostToolUse, Stop, SubagentStart, TeammateIdle等）を発火</li><li>各イベントが<code>curl</code>でOrchestraのローカルHTTPサーバー（port 3008）に送信</li><li>Orchestraがセッション状態を更新しデスクトップUIに表示</li><li>セッションが注意を必要とした時、キュー通知がJumpボタン付きで表示</li></ol>`,13)])])}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
